/* From Uiverse.io by escannord  - Tags: animation, loader, spinner */
.__UIV_SCOPE__ .loader {
  position: relative;
}
.__UIV_SCOPE__ .load {
  display: inline-block;
  height: calc(var(--i) * 15);
  width: calc(var(--i) * 15);
  background-color: transparent;
  position: absolute;
  border: 5px rgb(47, 0, 255) solid;
  border-top: none;
  border-radius: 50%;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  animation: turn 2s infinite linear;
}

.__UIV_SCOPE__ .load:nth-child(odd) {
  animation: turn 2s infinite linear reverse;
}

@keyframes turn {
  100% {
    transform: translate(-50%, -50%) rotateZ(360deg);
  }
}
